def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(row.count(c) for row in grid))
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)
            if len(cells) != 2 * (maxr - minr + 1) + 2 * (maxc - minc + 1) - 4:
                continue
            if all(grid[minr][x] == color and grid[maxr][x] == color for x in range(minc, maxc + 1)) and \
               all(grid[y][minc] == color and grid[y][maxc] == color for y in range(minr, maxr + 1)):
                fill = 7 if (maxr - minr + 1) % 2 else 2
                for y in range(minr + 1, maxr):
                    for x in range(minc + 1, maxc):
                        if grid[y][x] == bg:
                            out[y][x] = fill
    return out
